def binary_search_iterative(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_recursive(arr, target, low, high):
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, high)
    else:
        return binary_search_recursive(arr, target, low, mid - 1)

numbers = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
print(f"Searching in: {numbers}")
print(f"Find 23 (iter): {binary_search_iterative(numbers, 23)}")
print(f"Find 23 (rec): {binary_search_recursive(numbers, 23, 0, len(numbers)-1)}")
print(f"Find 99: {binary_search_iterative(numbers, 99)}")

